// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection, ArrayLike } from '@stdlib/types/array';

/**
* Data set instance.
*/
interface DataSet {
	/**
	* Serializes an instance to a JSON object.
	*
	* @returns JSON object
	*/
	toJSON(): object;
}

/**
* Converts a list of object arrays to "tidy" data sets.
*
* @param arr - list of arrays
* @param names - data set names
* @param mapping - object mapping existing field names to new field names
* @returns list of data sets
*
* @example
* var x = [
*     {
*         'a': 1,
*         'b': 2
*     },
*     {
*         'a': 3,
*         'b': 4
*     }
* ];
*
* var y = [
*     {
*         'a': 5,
*         'b': 6
*     },
*     {
*         'a': 7,
*         'b': 8
*     }
* ];
*
* var mapping = {
*     'a': 'x',
*     'b': 'y'
* };
* var v = objarrays2tidy( [ x, y ], [ 'data1', 'data2' ], mapping );
* // returns [ <DataSet>, <DataSet> ]
*/
declare function objarrays2tidy( arr: ArrayLike<Collection<object>>, names: ArrayLike<string>, mapping?: Record<string, string> ): Array<DataSet>;


// EXPORTS //

export = objarrays2tidy;
